struct GamepadSerialEvent {
    std::string event;
    json data;
    unsigned long long actionPower=0; // zero = state/cleanup notification, not a queued user action
    unsigned long long actionRevision=0; // zero = ordinary state/return notification
    // The event type carries the same fence in every extracted producer/consumer.
    // No new worker, polling, device authority, or keyboard/OEM epoch is owned here.
    static inline std::atomic<unsigned long long> ConfigurationRevision{1}, RulesRequired{0}, RulesApplied{0};
    static inline std::atomic<unsigned> ConfigurationWriters{0};
    static inline thread_local unsigned long long BoundRevision=0;
    static unsigned long long captureRevision() noexcept {
        return BoundRevision?BoundRevision:ConfigurationRevision.load(std::memory_order_acquire);
    }
    static bool currentRevision(unsigned long long revision) noexcept {
        if(!revision)return true;
        const auto observed=ConfigurationRevision.load(std::memory_order_acquire);
        const auto required=RulesRequired.load(std::memory_order_acquire);
        return revision==observed && !ConfigurationWriters.load(std::memory_order_acquire) &&
            RulesApplied.load(std::memory_order_acquire)==required &&
            ConfigurationRevision.load(std::memory_order_acquire)==observed;
    }
