        }
        ~ConfigurationWrite() noexcept {
            if(active){ConfigurationRevision.fetch_add(1,std::memory_order_acq_rel);ConfigurationWriters.fetch_sub(1,std::memory_order_release);}
        }
        ConfigurationWrite(const ConfigurationWrite&)=delete;
        ConfigurationWrite& operator=(const ConfigurationWrite&)=delete;
    };
    static void rulesPublished() noexcept {
        RulesRequired.fetch_add(1,std::memory_order_acq_rel);
        ConfigurationRevision.fetch_add(1,std::memory_order_acq_rel);
