void ipc_emit_owned_gyro_telemetry(std::string ev, json data) {
    UiCostIpcScope ipcCost(ev.c_str());
    if (!g_view && g_children.empty()) return;
    if (tickCostEnabled()) g_c17aOwnedEvents.fetch_add(1, std::memory_order_relaxed);
    if (!data.is_object()) data = json::object();
    // The old path is reconstructed only while diagnostics are enabled.  This
    // keeps the production path move-only while giving the short-screen run a
    // direct byte-for-byte guard over the complete WebView envelope.
    std::string referenceWire;
    if (tickCostEnabled()) {
        json reference = data;
        json oldEnvelope = {{"event", ev}, {"data", reference}};
        referenceWire = oldEnvelope.dump();
    }
    json m = {{"event", std::move(ev)}, {"data", std::move(data)}};
    std::optional<std::string> validatedWire;
    if (tickCostEnabled()) {
        if (referenceWire.empty()) {
            // The gate reopened without a reference. Preserve dump validation
            // and its exception point, but there is no parity comparison to count.
            validatedWire = m.dump();
        } else {
            g_c17aParityChecks.fetch_add(1, std::memory_order_relaxed);
            validatedWire = m.dump();
            if (*validatedWire != referenceWire) {
                g_c17aParityFailures.fetch_add(1, std::memory_order_relaxed);
                appendNativeLifecycleLog("c17a-gyro-wire-parity-mismatch", {});
            }
        }
    }
    ipc_broadcast_controller_snapshot(m, validatedWire ? &*validatedWire : nullptr);
}

void ipc_broadcast_controller_snapshot(const json& message, const std::string* validatedUtf8 = nullptr) {
    std::optional<std::wstring> wire;
    bool wireReady = false;
    const auto post = [&](int childId) {
        auto target = ipc_view_for_child(childId);
        if (!target) return;
        if (!wireReady) {
            std::optional<std::string> generatedUtf8;
            const std::string& utf8 = validatedUtf8 ? *validatedUtf8 : generatedUtf8.emplace(message.dump());
            if (utf8.empty()) {
                wire.emplace();
                wireReady = true;
            } else {
                const int n = MultiByteToWideChar(CP_UTF8, 0, utf8.c_str(), static_cast<int>(utf8.size()), nullptr, 0);
                auto& text = wire.emplace(n, L'\0');
                const int written = MultiByteToWideChar(CP_UTF8, 0, utf8.c_str(), static_cast<int>(utf8.size()), text.data(), n);
                wireReady = n > 0 && written == n;
            }
        }
        target->PostWebMessageAsJson(wire->c_str());
    };
    post(0);
    for (const auto& [id, cw] : g_children) {
        if (cw && cw->view) post(id);
    }
}
